"""Token savings dashboard for an empty or populated local tracking DB."""
import json
import os
import sqlite3
import sys
from datetime import date, timedelta

NO_DATA = "No tracking data yet.\nRun some rtk commands to start tracking savings.\n"


def _database():
    base = os.environ.get("XDG_DATA_HOME") or os.path.join(os.path.expanduser("~"), ".local", "share")
    return os.path.join(base, "rtk", "history.db")


def _rows(args):
    db = _database()
    if not os.path.exists(db):
        return []
    try:
        con = sqlite3.connect(db)
        if "-p" in args or "--project" in args:
            rows = con.execute("SELECT timestamp, input_tokens, output_tokens, saved_tokens, savings_pct, exec_time_ms FROM commands WHERE project_path = ? ORDER BY timestamp", (os.getcwd(),)).fetchall()
        else:
            rows = con.execute("SELECT timestamp, input_tokens, output_tokens, saved_tokens, savings_pct, exec_time_ms FROM commands ORDER BY timestamp").fetchall()
        con.close()
    except sqlite3.Error:
        return []
    return rows


def _summary(args):
    rows = _rows(args)
    if not rows:
        return None
    n = len(rows)
    inp = sum(r[1] or 0 for r in rows)
    out = sum(r[2] or 0 for r in rows)
    saved = sum(r[3] or 0 for r in rows)
    pct = (saved / inp * 100) if inp else 0.0
    elapsed = sum(r[5] or 0 for r in rows)
    return {"total_commands": n, "total_input": inp, "total_output": out,
            "total_saved": saved, "avg_savings_pct": pct,
            "total_time_ms": elapsed, "avg_time_ms": elapsed // n}


def _breakdowns(rows):
    daily, weekly, monthly = {}, {}, {}
    for row in rows:
        try:
            day = date.fromisoformat(str(row[0])[:10])
        except ValueError:
            continue
        start = day - timedelta(days=day.weekday())
        end = start + timedelta(days=6)
        keys = ((daily, day.isoformat()), (weekly, (start.isoformat(), end.isoformat())), (monthly, day.strftime("%Y-%m")))
        for bucket, key in keys:
            acc = bucket.setdefault(key, [0, 0, 0, 0, 0])
            acc[0] += 1
            acc[1] += row[1] or 0
            acc[2] += row[2] or 0
            acc[3] += row[3] or 0
            acc[4] += row[5] or 0
    def render(bucket, period):
        ret = []
        for key, (n, inp, out, saved, ms) in bucket.items():
            pct = saved / inp * 100 if inp else 0.0
            obj = {"commands": n, "input_tokens": inp, "output_tokens": out,
                   "saved_tokens": saved, "savings_pct": pct,
                   "total_time_ms": ms, "avg_time_ms": ms // n}
            if period == "daily": obj = {"date": key, **obj}
            elif period == "weekly": obj = {"week_start": key[0], "week_end": key[1], **obj}
            else: obj = {"month": key, **obj}
            ret.append(obj)
        return ret
    return {"daily": render(daily, "daily"), "weekly": render(weekly, "weekly"), "monthly": render(monthly, "monthly")}


def _command_stats(args):
