            rows = con.execute("SELECT rtk_cmd, COUNT(*), SUM(saved_tokens), AVG(savings_pct), SUM(exec_time_ms) FROM commands WHERE project_path = ? GROUP BY rtk_cmd", (os.getcwd(),)).fetchall()
        else:
            rows = con.execute("SELECT rtk_cmd, COUNT(*), SUM(saved_tokens), AVG(savings_pct), SUM(exec_time_ms) FROM commands GROUP BY rtk_cmd").fetchall()
