                    f"Tokens saved (lifetime): {saved}", f"Quota preserved:   {preserved:.1f}%", "",
                    "Note: Heuristic estimate based on ~44K tokens/5h (Pro baseline)",
                    "      Actual limits use rolling 5-hour windows, not monthly caps."])
    return "\n".join(out) + ("\n\n" if any(x in args for x in ("-H", "--history", "-g", "--graph")) else "\n")


