                  os.path.join(os.path.expanduser("~"), "Library", "Application Support", "rtk", "history.db")]
    for path in candidates:
        if not os.path.isfile(path):
            continue
        try:
            con = sqlite3.connect("file:" + path + "?mode=ro", uri=True)
            rows = con.execute("SELECT timestamp,input_tokens,output_tokens,saved_tokens,savings_pct FROM commands").fetchall()
            con.close()
            return rows
        except sqlite3.Error:
            continue
    return []


def _economic_series(rows, unit):
    grouped = defaultdict(list)
    for timestamp, inp, output, saved, pct in rows:
        label = str(timestamp)[:10]
        if unit == "weekly":
            try:
                day = date.fromisoformat(label)
                label = (day - timedelta(days=day.weekday()) + timedelta(days=2)).isoformat()
            except ValueError:
                pass
        if unit == "monthly":
            label = label[:7]
        grouped[label].append((inp or 0, output or 0, saved or 0, pct or 0.0))
    result = []
    for label in sorted(grouped):
        vals = grouped[label]
        saved_sum = sum(v[2] for v in vals)
        input_sum = sum(v[0] for v in vals)
        output_sum = sum(v[1] for v in vals)
        pct = (saved_sum / (input_sum + output_sum + saved_sum) * 100.0) if unit == "monthly" and input_sum + output_sum + saved_sum else sum(v[3] for v in vals) / len(vals)
        result.append({
            "label": label,
            "cc_cost": None,
            "cc_total_tokens": None,
            "cc_active_tokens": None,
            "cc_input_tokens": None,
            "cc_output_tokens": None,
            "cc_cache_create_tokens": None,
            "cc_cache_read_tokens": None,
            "rtk_commands": len(vals),
            "rtk_saved_tokens": saved_sum,
            "rtk_savings_pct": pct,
            "weighted_input_cpt": None,
            "savings_weighted": None,
            "blended_cpt": None,
            "active_cpt": None,
            "savings_blended": None,
            "savings_active": None,
        })
    return result


def _economic_totals(rows):
    saved = sum(row[3] or 0 for row in rows)
    inp = sum((row[1] or 0) + (row[2] or 0) + (row[3] or 0) for row in rows)
    return {
        "cc_cost": 0.0, "cc_total_tokens": 0, "cc_active_tokens": 0,
        "cc_input_tokens": 0, "cc_output_tokens": 0,
        "cc_cache_create_tokens": 0, "cc_cache_read_tokens": 0,
        "rtk_commands": len(rows), "rtk_saved_tokens": saved,
